use crate::triage::{self, Desk, Gated, Tone};

#[test]
fn names_and_order() {
    assert_eq!(Desk::ALL.map(Desk::key), ["billing", "technical", "account", "none_of_these"]);
    assert_eq!(Tone::ALL.map(Tone::label), ["calm", "annoyed", "angry"]);
    assert!(Tone::Angry > Tone::Calm);
}

#[tokio::test]
async fn decides_with_a_fake() {
    let state = serde_json::json!({"message": "My invoice is wrong and I am furious"});
    let backend = judgment::Fake::new()
        .noul("actionable", 0.9).unwrap()
        .choice("desk", [("billing", 0.8), ("technical", 0.1), ("account", 0.05), ("none_of_these", 0.05)], 0.8).unwrap()
        .score("tone", [0.1, 0.2, 0.7], 0.7).unwrap();
    let d = triage::decide(&backend, "jev-latest", &state).await.unwrap();
    assert!(d.actionable.yes);
    assert!(matches!(d.desk, Gated::Act { value: Desk::Billing, .. }));
    assert!(matches!(d.tone, Gated::Act { value: Tone::Angry, .. }));
    let backend = judgment::Fake::new()
        .noul("actionable", 0.5).unwrap()
        .choice("desk", [("billing", 0.4), ("technical", 0.3), ("account", 0.2), ("none_of_these", 0.1)], 0.4).unwrap()
        .score("tone", [0.8, 0.1, 0.1], 0.8).unwrap();
    let d = triage::decide(&backend, "jev-latest", &state).await.unwrap();
    assert!(!d.actionable.yes, "0.5 is under the 0.55 threshold");
    assert_eq!(d.desk.or_fallback(), Some(Desk::NoneOfThese), "0.4 is under the 0.45 bar");
}

