use crate::routing::{self, Desk, DuplicateOf, Gated, Offered, Tone};

#[test]
fn sends_what_the_rubric_sends() {
    let root = std::path::Path::new("REPO_ROOT");
    let text = std::fs::read_to_string(root.join("examples/jud/routing-cases.jud")).unwrap();
    let rubric = judgment::jud::Rubric::parse(routing::SOURCE).unwrap();
    for case in &judgment::jud::Cases::parse(&text).unwrap().cases {
        let pairs = |id: &str| -> Vec<(String, String)> {
            case.options.get(id).map_or_else(Vec::new, |o| {
                o.iter().map(|(k, v)| (k.clone(), v.as_str().unwrap().to_owned())).collect()
            })
        };
        let offered = Offered { desk: pairs("desk"), duplicate_of: pairs("duplicate_of") };
        assert_eq!(
            routing::questions(&case.state, &offered).unwrap(),
            rubric.lower(&case.state, &case.options).unwrap()
        );
    }
}

#[tokio::test]
async fn types_every_gate() {
    let state = serde_json::json!({
        "message": {"text": "Charged twice for #1042, refund it now."},
        "customer": {"recent_orders": ["#1042"], "open_tickets": [{"id": "T-1"}]}
    });
    let offered = Offered {
        desk: vec![("billing".into(), "Invoices".into()), ("technical".into(), "Errors".into())],
        duplicate_of: vec![("T-1".into(), "Charged twice".into())],
    };
    let backend = judgment::Fake::new()
        .choice("desk", [("billing", 0.55), ("technical", 0.25), ("none_of_these", 0.2)], 0.55).unwrap()
        .score("tone", [0.0, 0.1, 0.8, 0.1], 0.8).unwrap()
        .choice("duplicate_of", [("T-1", 0.5), ("none", 0.5)], 0.5).unwrap()
        .noul("refund_request", 0.65).unwrap();
    let d = routing::decide(&backend, "jev-latest", &state, &offered).await.unwrap();
    assert!(matches!(&d.desk, Gated::Act { value: Desk::Supplied(k), band: Some(b), .. } if k == "billing" && b == "confirm"));
    assert!(matches!(d.tone, Gated::Act { value: Tone::Angry, reached: Some(true), .. }));
    assert_eq!(d.duplicate_of.and_then(|g| g.or_fallback()), Some(DuplicateOf::NoneOption));
    assert_eq!(d.refund_request.map(|r| r.yes), Some(false), "strict: 0.65 is not above 0.65");
    let bare = serde_json::json!({"message": {"text": "Hello"}});
    let backend = judgment::Fake::new()
        .choice("desk", [("billing", 0.9), ("none_of_these", 0.1)], 0.9).unwrap()
        .score("tone", [0.9, 0.1, 0.0, 0.0], 0.9).unwrap();
    let offered = Offered { desk: vec![("billing".into(), "Invoices".into())], ..Offered::default() };
    let d = routing::decide(&backend, "jev-latest", &bare, &offered).await.unwrap();
    assert_eq!((d.duplicate_of, d.refund_request), (None, None));
}

use crate::handoff;

#[tokio::test]
async fn decides_every_turn_from_the_recordings() {
    let root = std::path::Path::new("REPO_ROOT");
    let backend = judgment::Replay::open(&root.join("examples/recordings/jud_calibration")).unwrap();
    let text = std::fs::read_to_string(root.join("examples/jud/handoff-cases.jud")).unwrap();
    let mut asked = 0;
    for case in &judgment::jud::Cases::parse(&text).unwrap().cases {
        let turns = case.state.as_array().unwrap();
        for k in 0..turns.len() {
            let so_far = serde_json::Value::Array(turns[..=k].to_vec());
            let d = handoff::decide(&backend, "jev-latest", &so_far).await.unwrap();
            let _: handoff::YesNo = d.wants_human;
            asked += 1;
        }
    }
    assert_eq!(asked, 6);
}

use crate::edge_names::{self, ErrorChoice, Gated, SupportLevelV2, YesNo};

#[test]
fn names_follow_the_rules() {
    assert_eq!(
        ErrorChoice::ALL.map(ErrorChoice::key),
        ["self", "3d", "a-b", "a_b", "none of these"]
    );
    assert_eq!(
        ErrorChoice::ALL,
        [ErrorChoice::SelfOption, ErrorChoice::N3d, ErrorChoice::AB, ErrorChoice::AB2, ErrorChoice::NoneOfThese]
    );
    assert_eq!(SupportLevelV2::ALL.map(SupportLevelV2::label), ["low", "very high!", "!!!"]);
    assert_eq!(SupportLevelV2::ALL, [SupportLevelV2::Low, SupportLevelV2::VeryHigh, SupportLevelV2::Level2]);
}

#[tokio::test]
async fn decides_with_a_fake() {
    let backend = judgment::Fake::new()
        .noul("type", 0.8).unwrap()
        .score("support-level.v2", [0.1, 0.8, 0.1], 0.8).unwrap()
        .choice("error", [("self", 0.1), ("3d", 0.1), ("a-b", 0.2), ("a_b", 0.5), ("none of these", 0.1)], 0.5).unwrap();
    let d = edge_names::decide(&backend, "jev-latest", &serde_json::json!({"message": "?"})).await.unwrap();
    let t: YesNo = d.r#type;
    assert!(t.yes);
    assert!(matches!(d.support_level_v2, Gated::Act { value: SupportLevelV2::VeryHigh, .. }));
    assert_eq!(d.error.or_fallback(), Some(ErrorChoice::NoneOfThese), "0.5 is under the 0.6 bar");
    assert_eq!(d.q_2fa, None, "asked only when the state has `account`");
}

use crate::screening::{self, Gated, Reason, Tone};

#[tokio::test]
async fn decides_with_a_fake() {
    assert_eq!(Reason::ALL.map(Reason::key), ["duplicate_charge", "unhappy", "cancelled", "none_of_these"]);
    let backend = judgment::Fake::new()
        .noul("refund_request", 0.9).unwrap()
        .choice("reason", [("duplicate_charge", 0.7), ("unhappy", 0.1), ("cancelled", 0.1), ("none_of_these", 0.1)], 0.7).unwrap()
        .score("tone", [0.1, 0.2, 0.7], 0.7).unwrap();
    let d = screening::decide(&backend, "jev-latest", &serde_json::json!({"message": "Charged twice!"})).await.unwrap();
    assert!(d.refund_request.yes);
    assert!(matches!(d.reason, Some(Gated::Act { value: Reason::DuplicateCharge, .. })));
    assert!(matches!(d.tone, Gated::Act { value: Tone::Angry, reached: Some(true), .. }));
    let backend = judgment::Fake::new()
        .noul("refund_request", 0.1).unwrap()
        .score("tone", [0.9, 0.1, 0.0], 0.9).unwrap();
    let d = screening::decide(&backend, "jev-latest", &serde_json::json!({"other": 1})).await.unwrap();
    assert_eq!(d.reason, None, "asked only when the state has `message`");
}

